  "platform.trust.notice.description": {
    en: "Items below marked as requiring an external gate are things we do not have. Nothing here has been reviewed by counsel or verified by an external auditor. Ask us for the current status of anything listed under “{section}” and you will get a date, not a document.",
    es: "Los elementos de más abajo marcados como dependientes de un requisito externo son cosas que no tenemos. Nada de lo que aparece aquí ha sido revisado por la asesoría jurídica ni verificado por un auditor externo. Si nos pregunta por el estado actual de cualquier elemento de «{section}», recibirá una fecha, no un documento.",
    fr: "Les éléments ci-dessous marqués comme nécessitant un prérequis externe sont des choses dont nous ne disposons pas. Rien ici n’a été examiné par un conseil juridique ni vérifié par un auditeur externe. Si vous nous demandez où en est un élément de la section «\u00a0{section}\u00a0», vous obtiendrez une date, pas un document.",
    de: "Die unten als abhängig von einer externen Voraussetzung markierten Punkte sind Dinge, die wir nicht haben. Nichts hier wurde von der Rechtsberatung geprüft oder von einem externen Prüfer verifiziert. Wenn Sie uns nach dem aktuellen Stand eines Punkts unter „{section}“ fragen, erhalten Sie ein Datum, kein Dokument.",
    ja: "下記で外部要件が必要と記載されている項目は、当社が有していないものです。ここに記載された内容は、法務顧問による確認も外部監査人による検証も受けていません。「{section}」に記載された項目の現状をお問い合わせいただいた場合、お伝えできるのは文書ではなく日付です。",
    pt: "Os itens abaixo marcados como dependentes de um pré-requisito externo são coisas que não temos. Nada aqui foi revisado pela assessoria jurídica nem verificado por um auditor externo. Se você nos perguntar sobre a situação atual de qualquer item em “{section}”, receberá uma data, não um documento.",
    zh: "下文标注为需要外部前置条件的项目，是我们不具备的内容。此处内容均未经法律顾问审核，也未经外部审计师验证。如您询问“{section}”中任何项目的当前状态，我们提供的将是日期，而不是文件。",
    ar: "البنود أدناه المعلَّمة بأنها مرهونة بمتطلب خارجي هي أمور لا نملكها. لم يراجع المستشار القانوني أي شيء هنا، ولم يتحقق منه مدقق خارجي. وإذا سألتنا عن الوضع الحالي لأي بند مدرج تحت «{section}» فستحصل على تاريخ لا على مستند.",
  },
