  "platform.trust.footnote": {
    en: "This page is rendered from the source of the deployment you are reading it on. There is no separate publication step and no copy kept anywhere else, so it cannot be out of date relative to that deployment. It can still be behind changes we have merged since.",
    es: "Esta página se genera a partir del código fuente del despliegue en el que la está leyendo. No hay un paso de publicación aparte ni una copia guardada en otro lugar, así que no puede estar desactualizada respecto a ese despliegue. Sí puede ir por detrás de cambios que hayamos incorporado después.",
    fr: "Cette page est générée à partir du code source du déploiement sur lequel vous la lisez. Il n’y a pas d’étape de publication distincte ni de copie conservée ailleurs\u202f; elle est donc forcément à jour par rapport à ce déploiement. Elle peut en revanche être en retard sur des modifications que nous avons fusionnées depuis.",
    de: "Diese Seite wird aus dem Quellcode der Bereitstellung erzeugt, auf der Sie sie lesen. Es gibt keinen separaten Veröffentlichungsschritt und keine anderswo aufbewahrte Kopie, daher kann sie gegenüber dieser Bereitstellung nicht veraltet sein. Sie kann aber hinter Änderungen zurückliegen, die wir seitdem zusammengeführt haben.",
    ja: "このページは、ご覧になっているデプロイメントのソースから生成されています。別途の公開手順も、他の場所に保管されたコピーもないため、そのデプロイメントに対して最新でなくなることはありません。ただし、その後に当社がマージした変更は反映されていない場合があります。",
    pt: "Esta página é gerada a partir do código-fonte da implantação em que você a está lendo. Não há uma etapa de publicação separada nem uma cópia guardada em outro lugar, então ela não pode estar desatualizada em relação a essa implantação. Ela ainda pode estar atrás de alterações que incorporamos depois.",
    zh: "本页由您正在访问的部署的源代码生成。没有单独的发布步骤，也没有在其他地方保存副本，因此相对于该部署始终是最新的。但它可能尚未包含我们此后合并的更改。",
    ar: "تُنشأ هذه الصفحة من الشيفرة المصدرية لعملية النشر التي تقرؤها عليها. ولا توجد خطوة نشر منفصلة ولا نسخة محفوظة في مكان آخر، لذا لا يمكن أن تكون غير محدّثة مقارنةً بعملية النشر تلك. لكنها قد تتأخر عن تغييرات دمجناها بعد ذلك.",
  },

