  "platform.developers.lede.spec": {
    en: "The machine-readable contract is at {link}, and a typed client is generated from the same document. Group names, paths and parameter names appear exactly as the contract writes them. None of the reference below is maintained by hand, so it cannot fall behind the API.",
    es: "La especificación legible por máquina está en {link}, y a partir de ese mismo documento se genera un cliente tipado. Los nombres de grupo, las rutas y los nombres de parámetro aparecen tal como los escribe la especificación. Nada de la referencia que sigue se mantiene a mano, así que no puede quedarse desfasada respecto a la API.",
    fr: "La spécification lisible par machine se trouve à l’adresse {link}, et un client typé est généré à partir de ce même document. Les noms de groupe, les chemins et les noms de paramètre apparaissent tels que la spécification les écrit. Rien dans la référence ci-dessous n’est maintenu à la main\u202f; elle ne peut donc pas prendre de retard sur l’API.",
    de: "Die maschinenlesbare Spezifikation liegt unter {link}; aus genau diesem Dokument wird ein typisierter Client erzeugt. Gruppennamen, Pfade und Parameternamen erscheinen so, wie die Spezifikation sie schreibt. Nichts in der folgenden Referenz wird von Hand gepflegt, daher kann sie nicht hinter der API zurückbleiben.",
    ja: "機械可読の仕様は {link} にあり、型付きクライアントも同じドキュメントから生成されます。グループ名、パス、パラメーター名は仕様の記載どおりに表示しています。以下のリファレンスは手作業で管理していないため、API より古くなることはありません。",
    pt: "A especificação legível por máquina está em {link}, e um cliente tipado é gerado a partir desse mesmo documento. Nomes de grupo, caminhos e nomes de parâmetro aparecem exatamente como a especificação os escreve. Nada na referência abaixo é mantido manualmente, então ela não fica defasada em relação à API.",
    zh: "机器可读的规范位于 {link}，类型化客户端也由同一份文档生成。分组名称、路径和参数名称均按规范原文显示。以下参考内容均非手工维护，因此不会落后于 API。",
    ar: "المواصفات القابلة للقراءة آلياً متاحة على {link}، ومن المستند نفسه يُولَّد عميل مضبوط الأنواع. تظهر أسماء المجموعات والمسارات وأسماء المعاملات كما تكتبها المواصفات تماماً. لا يُحدَّث أي جزء من المرجع أدناه يدوياً، لذا لا يمكن أن يتخلّف عن API.",
  },
