  "platform.developers.credential.missing.body": {
    en: "A cookie is issued by an interactive sign-in and belongs to a browser, so there is no credential you could hold and present. Issuing, listing and revoking a machine credential is not built. The operations that do not need a session are not a way in either: they take a signature or a token this deployment issues, and they are named below. Read this reference as the shape of the API, not as an invitation to integrate against it today.",
    es: "Una cookie se emite al iniciar sesión de forma interactiva y pertenece a un navegador, así que no hay ninguna credencial que usted pueda guardar y presentar. La emisión, el listado y la revocación de credenciales de máquina no están implementados. Las operaciones que no requieren sesión tampoco son una vía de acceso: exigen una firma o un token emitido por este despliegue, y se enumeran más abajo. Lea esta referencia como la forma de la API, no como una invitación a integrarse con ella hoy.",
    fr: "Un cookie est émis lors d’une connexion interactive et appartient à un navigateur\u202f; il n’existe donc aucun identifiant que vous puissiez conserver et présenter. L’émission, la liste et la révocation d’identifiants machine ne sont pas implémentées. Les opérations qui n’exigent pas de session ne sont pas non plus une porte d’entrée\u00a0: elles attendent une signature ou un jeton émis par ce déploiement, et elles sont nommées ci-dessous. Lisez cette référence comme la forme de l’API, et non comme une invitation à vous y intégrer dès aujourd’hui.",
    de: "Ein Cookie wird bei einer interaktiven Anmeldung ausgestellt und gehört zu einem Browser; es gibt also keine Zugangsdaten, die Sie aufbewahren und vorlegen könnten. Das Ausstellen, Auflisten und Widerrufen von Maschinen-Zugangsdaten ist nicht umgesetzt. Die Operationen ohne Sitzung sind ebenfalls kein Zugang: Sie erwarten eine Signatur oder ein Token, das diese Umgebung ausstellt, und sind unten aufgeführt. Lesen Sie diese Referenz als Beschreibung der API-Struktur, nicht als Einladung, heute schon eine Integration darauf aufzubauen.",
    ja: "Cookie は対話型のサインインで発行され、ブラウザーに紐づくため、保持して提示できる認証情報はありません。マシン用認証情報の発行、一覧表示、失効は実装されていません。セッションを必要としないオペレーションも、アクセス手段にはなりません。これらには署名、またはこのデプロイメントが発行するトークンが必要で、以下に記載しています。このリファレンスは API の構造を示すものであり、現時点での連携を勧めるものではありません。",
    pt: "Um cookie é emitido por um login interativo e pertence a um navegador, então não existe credencial que você possa guardar e apresentar. A emissão, a listagem e a revogação de credenciais de máquina não foram implementadas. As operações que não exigem sessão também não são uma porta de entrada: elas exigem uma assinatura ou um token emitido por esta implantação e estão listadas abaixo. Leia esta referência como o formato da API, não como um convite para integrar-se a ela hoje.",
    zh: "Cookie 由交互式登录签发并归属于浏览器，因此不存在可供您持有和出示的凭证。机器凭证的签发、列出和吊销功能尚未实现。无需会话的操作同样不是接入途径：它们要求提供签名或由本部署签发的令牌，下文已逐一列出。请将本参考视为 API 的结构说明，而不是邀请您现在就进行集成。",
    ar: "يُصدَر ملف تعريف الارتباط (cookie) عند تسجيل دخول تفاعلي ويرتبط بمتصفح، لذا لا توجد بيانات اعتماد يمكنك الاحتفاظ بها وتقديمها. إصدار بيانات اعتماد الآلات وسردها وإبطالها غير منفَّذ. كما أن العمليات التي لا تحتاج إلى جلسة ليست منفذاً للدخول: فهي تتطلب توقيعاً أو رمزاً تُصدره هذه البيئة، وهي مذكورة أدناه. اقرأ هذا المرجع على أنه وصف لبنية API، لا دعوة إلى التكامل معها اليوم.",
  },
