  "platform.developers.authorization.body": {
    en: "That is a gap in the published contract rather than a statement about the handlers, but it is not one gap with one answer behind it. What each of those operations actually requires is set out below, class by class, and the classes are not interchangeable: {classes}. Check the class before you decide what an operation needs.",
    es: "Es una laguna de la especificación publicada, no una afirmación sobre los controladores, pero no es una única laguna con una única respuesta detrás. Lo que exige realmente cada una de esas operaciones se detalla más abajo, clase por clase, y las clases no son intercambiables: {classes}. Compruebe la clase antes de decidir qué necesita una operación.",
    fr: "C’est une lacune de la spécification publiée, et non un constat sur les gestionnaires, mais ce n’est pas une lacune unique avec une seule réponse derrière. Ce que chacune de ces opérations exige réellement est détaillé ci-dessous, classe par classe, et les classes ne sont pas interchangeables\u00a0: {classes}. Vérifiez la classe avant de décider de ce dont une opération a besoin.",
    de: "Das ist eine Lücke in der veröffentlichten Spezifikation, keine Aussage über die Handler – aber es ist nicht eine einzige Lücke mit einer einzigen Antwort dahinter. Was jede dieser Operationen tatsächlich verlangt, ist unten Klasse für Klasse aufgeführt, und die Klassen sind nicht austauschbar: {classes}. Prüfen Sie die Klasse, bevor Sie entscheiden, was eine Operation braucht.",
    ja: "これは公開仕様の欠落であって、ハンドラーの実装を述べたものではありません。ただし、欠落は一種類ではなく、答えも一つではありません。各オペレーションが実際に何を要求するかは、以下にクラスごとに示しています。クラスは互いに置き換えられません。内訳：{classes}。オペレーションに何が必要かを判断する前に、クラスを確認してください。",
    pt: "Isso é uma lacuna da especificação publicada, e não uma afirmação sobre os manipuladores, mas não é uma lacuna única com uma única resposta por trás. O que cada uma dessas operações realmente exige está detalhado abaixo, classe por classe, e as classes não são intercambiáveis: {classes}. Verifique a classe antes de decidir o que uma operação exige.",
    zh: "这是已发布规范中的缺漏，并不代表处理程序的实际行为；而且它并非只有一种情况、一个答案。这些操作各自实际需要什么，下文按类别逐一列出，各类别之间不可互换：{classes}。在判断某个操作需要什么之前，请先确认它属于哪个类别。",
    ar: "هذه ثغرة في المواصفات المنشورة وليست وصفاً للمعالجات، لكنها ليست ثغرة واحدة وراءها إجابة واحدة. ما تتطلبه كل عملية من هذه العمليات فعلاً مبيَّن أدناه فئةً فئة، والفئات غير قابلة للتبادل: {classes}. تحقّق من الفئة قبل أن تقرّر ما تحتاجه العملية.",
  },
