  "platform.developers.authentication.note": {
    en: "The classes below are small enough to name in full, so read them as the exceptions rather than as examples. An operation that is not in one of these lists and does not declare a scheme in the contract is in the browser-session row above.",
    es: "Las clases siguientes son lo bastante pequeñas como para enumerarlas completas, así que léalas como las excepciones y no como ejemplos. Una operación que no figura en ninguna de estas listas y no declara un esquema en la especificación pertenece a la fila de sesión del navegador de la tabla anterior.",
    fr: "Les classes ci-dessous sont assez restreintes pour être listées en entier\u202f; lisez-les comme les exceptions, et non comme des exemples. Une opération qui ne figure dans aucune de ces listes et ne déclare pas de schéma dans la spécification relève de la ligne consacrée à la session de navigateur dans le tableau ci-dessus.",
    de: "Die folgenden Klassen sind klein genug, um sie vollständig aufzuführen; lesen Sie sie daher als die Ausnahmen, nicht als Beispiele. Eine Operation, die in keiner dieser Listen steht und in der Spezifikation kein Schema deklariert, gehört zur Zeile „Browsersitzung“ in der Tabelle oben.",
    ja: "以下のクラスはすべて列挙できる規模のため、例ではなく例外として読んでください。これらのリストのいずれにも含まれず、仕様でスキームも宣言していないオペレーションは、上の表のブラウザーセッションの行に該当します。",
    pt: "As classes abaixo são pequenas o bastante para serem listadas por completo, então leia-as como as exceções, e não como exemplos. Uma operação que não está em nenhuma dessas listas e não declara um esquema na especificação pertence à linha de sessão do navegador na tabela acima.",
    zh: "以下类别规模很小，可以完整列出，因此请将它们视为例外，而非示例。凡不在这些列表中、且未在规范中声明方案的操作，都属于上表中的浏览器会话一行。",
    ar: "الفئات أدناه صغيرة بما يكفي لسردها كاملة، لذا اقرأها على أنها الاستثناءات لا الأمثلة. أي عملية لا ترد في أي من هذه القوائم ولا تُعلن مخططاً في المواصفات تندرج ضمن صف جلسة المتصفح في الجدول أعلاه.",
  },
